1	/**
2	 * Dispatch handler for reviewer-executor completions (handle.kind = "review").
3	 *
4	 * Routes by ReviewerResult.terminal_status:
5	 *   passed           → emit review_passed only. The task stays in_review.
6	 *                      handleMergedPrs is the single source of truth for "task
7	 *                      done": when the in_review PR poll sees the implementation
8	 *                      PR merged=true on GitHub (whether by the bot in Step 7 of
9	 *                      review-pr/SKILL.md or by a human merging later), it writes
10	 *                      status: done + auto-ready cascade + workspace PR merge.
11	 *   change_requested → mutate task YAML to change_requested
12	 *   escalate         → post Slack, mutate task YAML to blocked, emit task_escalated
13	 *   unknown          → emit review_result_unknown_status
14	 */
15	
16	import process from "node:process";
17	import type { ReviewerResult } from "@workflow/runtime-abi";
18	import { taskBranchName } from "../paths.js";
19	import { mutateTaskYamlDirect } from "./mutate-yaml-direct.js";
20	import { curlJson } from "../utils/curl-json.js";
21	import { readTask } from "../utils/task-yaml-io.js";
22	import { handleEscalation } from "./escalation-handler.js";
23	import type { NotificationPort } from "../notification/port.js";
24	
25	export type ReviewResult = ReviewerResult;
26	
27	export interface DispatchReviewResultOpts {
28	  result: ReviewResult;
29	  workspaceRoot: string;
30	  featureId: string;
31	  taskId: string;
32	  /** Task title from the task YAML — used in Slack escalation message. */
33	  taskTitle?: string;
34	  /** Implementation PR URL — used in Slack escalation message. */
35	  prUrl?: string;
36	  gitAuthorEmail: string;
37	  gitAuthorName?: string;
38	  sshKeyPath?: string;
39	  /** GitHub personal access token for the Handoff Trigger PR creation. Falls back to GITHUB_TOKEN env var. */
40	  githubToken?: string;
41	  /** Notification port — passed through to handleEscalation for task-tied escalation. */
42	  notifier?: NotificationPort | null;
43	  emit: (event: Record<string, unknown>) => void;
44	}
45	
46	export async function dispatchReviewResult(opts: DispatchReviewResultOpts): Promise<void> {
47	  const {
48	    result, workspaceRoot, featureId, taskId,
49	    taskTitle, prUrl,
50	    gitAuthorEmail, gitAuthorName, sshKeyPath,
51	    githubToken = process.env["GITHUB_TOKEN"] ?? "",
52	    notifier,
53	    emit,
54	  } = opts;
55	  const taskBranch = taskBranchName(featureId, taskId);
56	
57	  const prNumberMatch = prUrl ? /\/pull\/(\d+)/.exec(prUrl) : null;
58	  const prNumber = prNumberMatch ? Number(prNumberMatch[1]) : null;
59	
60	  switch (result.terminal_status) {
61	    case "passed": {
62	      // `terminal_status: passed` means the reviewer posted APPROVE. It does NOT
63	      // mean the implementation PR is merged. The reviewer may attempt the merge
64	      // in Step 7 of review-pr/SKILL.md, but the merge may be skipped
65	      // (`execution.requires_human_review === true`) or rejected (branch
66	      // protection requires a human approval). Either way, the task stays
67	      // `in_review` here; the in_review PR poll detects merged=true on GitHub
68	      // and handleMergedPrs writes the done state at that point.
69	      if (result.self_review_skipped) {
70	        emit({ type: "reviewer_self_review_skipped", task_id: taskId, feature_id: featureId,
71	               pr_number: prNumber });
72	      }
73	      emit({ type: "review_passed", task_id: taskId, feature_id: featureId,
74	             verdict: result.verdict, confidence: result.confidence, notes: result.notes, review_url: result.review_url });
75	      break;
76	    }
77	
78	    case "change_requested": {
79	      if (result.self_review_skipped) {
80	        emit({ type: "reviewer_self_review_skipped", task_id: taskId, feature_id: featureId,
81	               pr_number: prNumber });
82	      }
83	      const mutateErr = mutateTaskYamlDirect({
84	        workspaceRoot, featureId, taskId, taskBranch,
85	        status: "change_requested",
86	        logEntry: {
87	          action: "reviewer_complete",
88	          by: gitAuthorEmail,
89	          note: result.notes ?? "Reviewer requested changes.",
90	          // Persist the specific review URL so the fix agent can fetch exactly
91	          // this review's inline comments (precise) instead of "all unresolved
92	          // threads on the PR" (lossy across multiple review cycles).
93	          ...(result.review_url ? { review_url: result.review_url } : {}),
94	        },
95	        gitAuthorEmail, gitAuthorName, sshKeyPath,
96	        commitMessage: `chore(${taskId}): reviewer → change_requested`,
97	      });
98	      if (mutateErr) {
99	        emit({ type: "review_mutate_failed", task_id: taskId, feature_id: featureId, details: mutateErr });
100	        return;
101	      }
102	      emit({ type: "review_change_requested", task_id: taskId, feature_id: featureId,
103	             notes: result.notes, review_url: result.review_url });
104	      // Demote task PR back to draft while fixes are in progress
105	      if (prUrl && githubToken) {
106	        const prMatch = /github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/.exec(prUrl);
107	        if (prMatch) {
108	          const [, owner, repo, prNumber] = prMatch;
109	          try {
110	            curlJson([
111	              "-s", "-X", "PATCH",
112	              "-H", `Authorization: token ${githubToken}`,
113	              "-H", "Accept: application/vnd.github+json",
114	              "-H", "Content-Type: application/json",
115	              "-d", JSON.stringify({ draft: true }),
116	              `https://api.github.com/repos/${owner}/${repo}/pulls/${prNumber}`,
117	            ]);
118	          } catch (e) {
119	            emit({ type: "task_pr_demote_failed", task_id: taskId, feature_id: featureId, details: String(e) });
120	          }
121	        }
122	      }
123	      break;
124	    }
125	
126	    case "escalate":
127	      await handleEscalation({
128	        workspaceRoot, featureId, taskId,
129	        taskTitle, prUrl,
130	        notes: result.notes,
131	        reviewUrl: result.review_url,
132	        gitAuthorEmail, gitAuthorName, sshKeyPath,
133	        notifier,
134	        emit,
135	      });
136	      break;
137	
138	    default: {
