        { action: "review_blocked", by: GIT_AUTHOR_EMAIL, at: "2025-01-01T01:00:00Z", note: "attempt 2" },
      ],
    });
    const wsRoot = makeWorkspaceWithTasks([task]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/task/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "blocked" as never, verdict: undefined as never, confidence: 0, notes: "" },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      gitAuthorName: GIT_AUTHOR_NAME,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "review_incomplete")).toBe(true);
    expect(events.some((e) => e.type === "review_blocked_logged")).toBe(false);
    expect(events.some((e) => e.type === "task_escalated")).toBe(true);

    const updated = readTaskFromDir(wsRoot, TASK_ID);
    expect(updated.status).toBe("blocked");
  });

  it("MAX_REVIEW_INCOMPLETES=1: escalates after first incomplete", async () => {
    process.env["MAX_REVIEW_INCOMPLETES"] = "1";

    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, {
      status: "in_review",
      log: [{ action: "review_blocked", by: GIT_AUTHOR_EMAIL, at: "2025-01-01T00:00:00Z", note: "attempt 1" }],
    });
    const wsRoot = makeWorkspaceWithTasks([task]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/task/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "blocked" as never, verdict: undefined as never, confidence: 0, notes: "" },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      gitAuthorName: GIT_AUTHOR_NAME,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "task_escalated")).toBe(true);
    expect(events.some((e) => e.type === "review_blocked_logged")).toBe(false);

    const updated = readTaskFromDir(wsRoot, TASK_ID);
    expect(updated.status).toBe("blocked");
  });
});

