    const updated = readTaskFromDir(wsRoot, TASK_ID);
    const entry = updated.log.find((e) => e.action === "review_blocked");
    expect(entry).toBeDefined();
    expect(entry!.executor_audit).toEqual(auditFixture);
  });

  it("passed: spreads executor_audit onto reviewer_complete log entry", async () => {
    const { spawnSync: spMock } = await import("node:child_process");
