      },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: () => {},
    });

    const updated = readTaskFromDir(wsRoot, TASK_ID);
    const entry = updated.log.find((e) => e.action === "reviewer_complete");
    expect(entry).toBeDefined();
    expect(entry!.executor_audit).toEqual(auditFixture);
